mapper.select:
select u.U_Name as sendUserName, du.C_ID as cId, du.U_Name as taskUserName, f.FileTitle as fileTitle, f.FileCode as fileCode, f.FileFlowStatus as fileflowstatus, f.FileCreateDate as filecreatedate, f.FileCreateUser as filecreateuser, f.FileCreateUserName as filecreateusername, flow.FlowName as flowName, pro.P_Name as pName, sec.Sec_Name as secName, con.Con_Name as conName, f.T_Code as tCode,
from SYS_Task t left join SYS_User u on u.U_ID=t.TaskSendUser left join SYS_User du on du.U_ID=t.TaskUser left join SYS_File f on f.FileID=t.TaskEntityID left join SYS_Flow flow on flow.FlowID=t.TaskFlow left join Pre_Project pro on pro.P_ID=f.FileProject left join Sec_Info sec on sec.Sec_Id=f.FileSectionID left join Con_Contract con on con.Con_Id=f.FileContract
left join Sys_Task_Massage stm on stm.task_Id=t.taskId
1=1
and t.TaskUser in
#{userId}
and f.T_Code in
#{code}
and f.T_Code=#{params.tCode}
and t.TaskName like concat('%',#{params.taskname},'%')
and likePname(#{params.pName},pro.P_Id)=true
and pro.P_Name like concat('%',#{params.pName},'%')
and con.Con_Name like concat('%',#{params.conName},'%')
and u.U_Name like concat('%',#{params.taskSendUser},'%')
and du.U_Name like concat('%',#{params.taskUser},'%')
and sec.Sec_Name like concat('%',#{params.secName},'%')
and flow.FlowName like concat('%',#{params.flowName},'%')
and t.TaskSendTime >= #{params.taskSendTimeStart}
and #{params.taskSendTimeEnd} >= t.TaskSendTime
and f.FileCode like concat('%',#{params.fileCode},'%')
and du.U_Name like concat('%',#{params.taskUserName},'%')
and t.Te_Id = #{params.teId}
and stm.u_Ids= #{params.uId}
and (pro.P_Competent_Department in
#{code}
or ( pro.P_Id is null and t.TaskUser in
#{userId}
)
)
and t.TaskSendTime >= #{params.taskSendTimeStartMin}
order by t.${params.sortFiled} ${params.sortType}
order by ${params.sortSideFiled} ${params.sortType}
order by t.Taskendtime DESC
limit #{params.start},#{params.size}

        select
        COUNT(1)
        from SYS_Task t
        left join SYS_File f on f.FileID=t.TaskEntityID
        left join Pre_Project pro on pro.P_ID=f.FileProject
        left join Con_Contract con on con.Con_Id=f.FileContract
        left join SYS_User u on u.U_ID=t.TaskSendUser
        left join SYS_Flow flow on flow.FlowID=t.TaskFlow
        
            left join Sys_Task_Massage stm on stm.task_Id=t.taskId
        
        
            1=1
            
                and t.TaskUser in
                
                    #{userId}
                
            
            
                and f.T_Code=#{params.tCode}
            
            
                and t.TaskName like concat('%',#{params.taskname},'%')
            
            
                and pro.P_Name like concat('%',#{params.pName},'%')
            
            
                and con.Con_Name like concat('%',#{params.conName},'%')
            
            
                and u.U_Name like concat('%',#{params.taskSendUser},'%')
            
            
                and du.U_Name like concat('%',#{params.taskUser},'%')
            
            
                and flow.FlowName like concat('%',#{params.flowName},'%')
            
            
                and t.TaskSendTime >= #{params.taskSendTimeStart}
            
            
                and #{params.taskSendTimeEnd} >= t.TaskSendTime
            
            
                and t.Te_Id = #{params.teId}
            
            
                and stm.u_Ids= #{params.uId}
            
            
                
                    and (pro.P_Competent_Department in
                    
                        #{code}
                    
                    
                        or ( pro.P_Id is null and
                        t.TaskUser in
                        
                            #{userId}
                        
                        )
                    
                    )
                
                
                    and t.TaskSendTime >= #{params.taskSendTimeStartMin}

select u.U_Name as sendUserName, u1.U_Name as taskUserName, f.FileTitle as fileTitle, f.FileCode as fileCode, f.FileFlowStatus as fileflowstatus, f.FileCreateDate as filecreatedate, f.FileCreateUser as filecreateuser, f.FileCreateUserName as filecreateusername, flow.FlowName as flowName, pro.P_Name as pName, sec.Sec_Name as secName, con.Con_Name as conName, f.T_Code as tCode,
from SYS_Task t left join SYS_User u on u.U_ID=t.TaskSendUser left join SYS_User u1 on u1.U_ID=t.TaskUser left join SYS_File f on f.FileID=t.TaskEntityID left join SYS_Flow flow on flow.FlowID=t.TaskFlow left join Pre_Project pro on pro.P_ID=f.FileProject left join Sec_Info sec on sec.Sec_Id=f.FileSectionID left join Con_Contract con on con.Con_Id=f.FileContract
1=1
and t.TaskName like concat('%',#{params.taskname},'%')
and pro.P_Name like concat('%',#{params.pName},'%')
and con.Con_Name like concat('%',#{params.conName},'%')
and u.U_Name like concat('%',#{params.taskSendUser},'%')
and u1.U_Name like concat('%',#{params.taskUser},'%')
and t.TaskEntityID =#{params.fileId}
and t.TaskSendUser =#{params.taskSendUserId}
and sec.Sec_Name like concat('%',#{params.secName},'%')
and t.Te_Id = #{params.teId}
order by t.${params.sortFiled} ${params.sortType}
limit #{params.start},#{params.size}

select COUNT(1) from SYS_Task t left join SYS_File f on f.FileID=t.TaskEntityID left join Pre_Project pro on pro.P_ID=f.FileProject left join Con_Contract con on con.Con_Id=f.FileContract left join SYS_User u on u.U_ID=t.TaskSendUser left join SYS_User u1 on u1.U_ID=t.TaskUser
1=1
and t.TaskName like concat('%',#{params.taskname},'%')
and pro.P_Name like concat('%',#{params.pName},'%')
and con.Con_Name like concat('%',#{params.conName},'%')
and u1.U_Name like concat('%',#{params.taskUser},'%')
and u.U_Name like concat('%',#{params.taskSendUser},'%')
and t.TaskEntityID =#{params.fileId}
and t.TaskSendUser =#{params.taskSendUserId}
and t.Te_Id = #{params.teId}

select sf.ActID as actid, sf.ActName as actname, sf.Act_Auto_Completion as actAutoCompletion, sf.Act_Triggert_Time as actTriggertTime, sf.Act_Auto_Multiple as actAutoMultiple, sf.Act_Auto_Completion_K as actAutoCompletionK, sf.Act_Auto_Completion_T as actAutoCompletionT, sf.Act_Auto_Default_Opinion as actAutoDefaultOpinion, sf.Act_Auto_Trigger_Field as actAutoTriggerField, case when (sf.Act_Auto_Trigger_Field is not null and sf.Act_Auto_Trigger_Field != '') then approvalTimes(t.TaskStartTime,#{params.newDate},#{params.festivalHoliday},#{params.workTimeType},#{params.workShift},#{params.closingTime}) else null end as elapsedHours,
from SYS_Task t left join SYS_FlowActivity sf on t.TaskCurrentActID=sf.ActID where Act_Auto_Completion='1' and ( ( (sf.Act_Auto_Trigger_Field is null or sf.Act_Auto_Trigger_Field = '') and approvalTimes(t.TaskStartTime,#{params.newDate},#{params.festivalHoliday},#{params.workTimeType},#{params.workShift},#{params.closingTime})>sf.Act_Triggert_Time ) or ( sf.Act_Auto_Trigger_Field is not null and sf.Act_Auto_Trigger_Field != '' ) ) and t.TaskID not in (select Task_Id from Sys_Task_Auto_Complete_Log where Task_Id is not null)
and t.Te_Id = #{params.teId}

select f.T_Code as tCode,
count(*) as total
from Sys_Task tk
left join Sys_File f on f.FileId=tk.TaskEntityId
where f.T_Code in

    #{code}


    and tk.TaskUser=#{params.uId}


    and tk.Te_Id = #{params.teId}

group by f.T_Code

select uer.U_Name as uName, uer.U_ID as uId, sf.FileProject as pId, st.TaskID as taskId, st.TaskCurrentActID as actId, st.TaskEntityID as taskEntityId from SYS_Task st left join SYS_User uer on uer.U_ID=st.TaskUser left join SYS_File sf on sf.FileID=TaskEntityID WHERE 1=1
and uer.U_Name like concat('%',#{params.uName},'%')
and uer.U_Type=#{params.uType}
and st.Te_Id = #{params.teId}

select t2.*, pre_project.P_Name as pName, u.U_Name as createName, u1.U_Name as doUserName, sys_file.FileCreateUser as fileCreateId, sys_file.FileCreateUserName as fileCreateName, sys_file.FileFlowStatus as fileFlowStatusc, sys_file.T_Code as tCode from (select '待办' as taskType, Task_Return_Type as taskReturnType, TaskID as taskId, TaskID as ctTaskid, TaskName as taskName, TaskUser as doUserId, TaskSendTime as createtime, TaskEntityID as fileId, TaskEntityID as taskentityid, TaskSendUser as createId, TaskCurrentActID as actId from sys_task where 1=1
and TaskUser in
#{userId}
and TaskName like concat('%',#{params.taskname},'%')
and TaskName in
#{taskname}
UNION select '沟通' as taskType, '' as taskReturnType, CT_ID as taskId, CT_TaskID as ctTaskid, CT_Name as taskName, CT_User as doUserId, CT_Time as createtime, CT_FileID as fileId , CT_FileID as taskentityid, CT_SendUser as createId, CT_ActID as actId from sys_coordinationtask where 1=1
and CT_User in
#{userId}
and CT_Name like concat('%',#{params.taskname},'%')
and CT_Name in
#{taskname}
)t2 left join sys_file on t2.fileId = sys_file.FileID left join pre_project on sys_file.FileProject = pre_project.P_ID left join SYS_User u on u.U_ID=t2.createId left join SYS_User u1 on u1.U_ID=t2.doUserId where 1=1
order by t2.${params.sortFiled} ${params.sortType}
limit #{params.start},#{params.size}

select count(1) from (select '待办' as taskType, TaskID as taskId, TaskName as taskName, TaskUser as doUserId, TaskSendTime as createtime, TaskEntityID as fileId, TaskSendUser as createId from sys_task where 1=1
and TaskUser in
#{userId}
and TaskName like concat('%',#{params.taskname},'%')
and TaskName in
#{taskname}
UNION select '沟通' as taskType, CT_ID as taskId, CT_Name as taskName, CT_User as doUserId, CT_Time as createtime, CT_FileID as fileId , CT_SendUser as createId from sys_coordinationtask where 1=1
and CT_User in
#{userId}
and CT_Name like concat('%',#{params.taskname},'%')
and CT_Name in
#{taskname}
) t2 left join sys_file on t2.fileId = sys_file.FileID left join pre_project on sys_file.FileProject = pre_project.P_ID left join SYS_User u on u.U_ID=t2.createId left join SYS_User u1 on u1.U_ID=t2.doUserId where 1=1

select DISTINCT ${key} from (select '待办' as taskType, TaskID as taskId, TaskName as taskName, TaskUser as doUserId, TaskSendTime as createtime, TaskEntityID as fileId, TaskSendUser as createId from sys_task where 1=1
and TaskUser in
#{userId}
and TaskName like concat('%',#{params.taskname},'%')
and TaskName in
#{taskname}
UNION select '沟通' as taskType, CT_ID as taskId, CT_Name as taskName, CT_User as doUserId, CT_Time as createtime, CT_FileID as fileId , CT_SendUser as createId from sys_coordinationtask where 1=1
and CT_User in
#{userId}
and CT_Name like concat('%',#{params.taskname},'%')
and CT_Name in
#{taskname}
)t2 left join sys_file on t2.fileId = sys_file.FileID left join pre_project on sys_file.FileProject = pre_project.P_ID left join SYS_User u on u.U_ID=t2.createId left join SYS_User u1 on u1.U_ID=t2.doUserId where 1=1

select count(1) from SYS_File mn left join Pre_Project pp on pp.P_ID = mn.FileProject left join Con_Contract con on con.Con_Id = mn.FileContract left join Sec_Info sec on sec.Sec_Id = mn.FileSectionID
and mn.FileTitle is not null and mn.T_Code is not null
and mn.FileCreateUser = #{uId}
and mn.Te_Id = #{customerId}
and mn.FileFlowStatus in
#{state}

sql.where:
and mn.FileTitle is not null
and mn.T_Code is not null

    and mn.FileCreateUser = #{uId}


    and mn.Te_Id = #{customerId}


    and mn.FileFlowStatus in
    
        #{state}
    


    and pp.P_Name like concat('%',#{params.pName},'%')


    and mn.FileTitle like concat('%',#{params.filetitle},'%')


    and mn.FileCode like concat('%',#{params.filecode},'%')


    and mn.T_Code like concat('%',#{params.tCode},'%')


    and con.Con_Name like concat('%',#{params.conName},'%')


    and con.Con_Name in
    
        #{conName}
    


    and mn.FileTitle in
    
        #{fileId}
    


    and pp.P_Name in
    
        #{pName}
    


    and mn.FileCreateDate = #{params.fileCreateDate}


    and mn.FileCreateDate >= #{params.fileCreateDateStart}


    and #{params.fileCreateDateEnd} >= mn.FileCreateDate


    and mn.FileFlowStatus in
    
        #{fileflowstatus}
    


    and mn.FileCreateDate >= #{params.startTime}


    and #{params.endTime} >= mn.FileCreateDate


    and sec.Sec_Name like concat('%',#{params.secName},'%')


    and sec.Sec_Name in
    
        #{secName}
